
(function(){
  const micUrl='data:image/webp;base64,';
  function speechCtor(){ return window.SpeechRecognition || window.webkitSpeechRecognition; }
  function appendText(el, text){
    const trimmed=(text||'').trim();
    if(!trimmed) return;
    const spacer=el.value && !el.value.endsWith(' ') && !el.value.endsWith('\\n') ? ' ' : '';
    el.value=(el.value||'')+spacer+trimmed;
    el.dispatchEvent(new Event('input',{bubbles:true}));
    el.dispatchEvent(new Event('change',{bubbles:true}));
  }
  function regionLooksSocial(el){
    const region=el.closest('.modal-window,.marketing-form-grid,.page-stack,.panel,section,form,label');
    const text=(region && region.innerText || '').toLowerCase();
    return text.includes('create social media idea') || text.includes('social media idea title') || text.includes('social media idea') || text.includes('social plan');
  }
  function canEnhance(el){
    if(!el || el.dataset.planufV14Dictate==='1') return false;
    if(!(el instanceof HTMLTextAreaElement) && !(el instanceof HTMLInputElement)) return false;
    const type=(el.getAttribute('type')||'text').toLowerCase();
    if(el instanceof HTMLInputElement && !['text','search','url','email','tel'].includes(type)) return false;
    if(el.closest('.content-piece-card')) return false;
    if(el.closest('.dictation-wrap')) return false;
    return regionLooksSocial(el);
  }
  function enhanceField(el){
    if(!canEnhance(el)) return;
    el.dataset.planufV14Dictate='1';
    const wrap=document.createElement('span');
    wrap.className='dictation-wrap planuf-v14-runtime-dictation';
    el.parentNode.insertBefore(wrap, el);
    wrap.appendChild(el);
    const btn=document.createElement('button');
    btn.type='button';
    btn.className='dictate-button planuf-v14-social-dictate';
    btn.setAttribute('aria-label','Use in-app speech to text');
    btn.title='Use in-app speech to text';
    btn.innerHTML='<span class="mic-icon" aria-hidden="true"></span><span class="sr-only">Dictate</span>';
    btn.addEventListener('click', function(){
      const Ctor=speechCtor();
      if(!Ctor) return;
      const rec=new Ctor();
      rec.lang='en-GB';
      rec.interimResults=false;
      rec.continuous=false;
      btn.classList.add('listening');
      rec.onresult=function(ev){
        let out='';
        for(let i=ev.resultIndex;i<ev.results.length;i++){
          if(ev.results[i] && ev.results[i].isFinal) out+=ev.results[i][0].transcript;
        }
        appendText(el,out);
      };
      rec.onend=function(){btn.classList.remove('listening');};
      rec.onerror=function(){btn.classList.remove('listening');};
      rec.start();
    });
    wrap.appendChild(btn);
  }
  function scan(){
    document.querySelectorAll('textarea,input[type="text"],input:not([type])').forEach(enhanceField);
  }
  const obs=new MutationObserver(scan);
  if(document.body){ obs.observe(document.body,{childList:true,subtree:true}); scan(); }
  else document.addEventListener('DOMContentLoaded', function(){ obs.observe(document.body,{childList:true,subtree:true}); scan(); });
})();
